class Fordon:

    def __init__(self, märke, antal_hjul):
        self.märke = märke
        self.antal_hjul = antal_hjul

    def __str__(self):
        return self.märke + " med " + str(self.antal_hjul) + " hjul"


class Cykel(Fordon):

    def __init__(self, märke, antal_växlar):
        super().__init__(märke, 2)       # en cykel har alltid 2 hjul
        self.antal_växlar = antal_växlar

    def __str__(self):
        text = super().__str__()
        return text + " och " + str(self.antal_växlar) + " växlar"


def main():
    bil = Fordon("Volvo", 4)
    print(bil)
    cykel = Cykel("Crescent", 7)
    print(cykel)

main()
